<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class FoundPropertyService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access) {}
    private function item(string $id):array {$r=$this->row('found_property','property_id',$id);$this->access->requireSite($r['site_id']);return $r;}
    public function list(array $input):array {$this->fields($input,['site_id']);$s=$this->access->requireSite($input['site_id']??null);$rows=$this->db->fetchAll('SELECT property_id,site_id,description,found_location,storage_location,found_at,photo_sha256,state,revision,created_at FROM found_property WHERE company_id=:company AND site_id=:site ORDER BY property_id DESC LIMIT 300',['company'=>$this->company(),'site'=>$s['site_id']]);foreach($rows as&$r)$r['history']=$this->db->fetchAll('SELECT event_id,event_type,notes,claimant_name,signature_sha256,storage_location,actor_user_id,occurred_at FROM found_property_events WHERE company_id=:company AND property_id=:id ORDER BY event_id',['company'=>$this->company(),'id'=>$r['property_id']]);unset($r);return $rows;}
    public function create(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['site_id','description','found_location','storage_location','found_at','photo_base64']);$s=$this->access->requireSite($input['site_id']??null);$photo=WorkflowMedia::image($input['photo_base64']??null);$at=$this->at($input['found_at']??null);if(strtotime($at.' UTC')>time()+300)throw HttpException::unprocessable('Found time cannot be in the future.');$this->db->execute('INSERT INTO found_property(company_id,site_id,description,found_location,storage_location,found_at,photo_base64,photo_mime,photo_sha256,created_by_user_id,created_at) VALUES(:company,:site,:description,:found,:storage,:at,:photo,:mime,:hash,:actor,:now)',['company'=>$this->company(),'site'=>$s['site_id'],'description'=>$this->text($input['description']??null,2000),'found'=>$this->text($input['found_location']??null,300),'storage'=>$this->text($input['storage_location']??null,300),'at'=>$at,'photo'=>$photo['base64'],'mime'=>$photo['mime'],'hash'=>$photo['sha256'],'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('found_property');});}
    public function photo(string $id):array {$r=$this->item($id);$bytes=base64_decode($r['photo_base64'],true);if($bytes===false||!hash_equals($r['photo_sha256'],hash('sha256',$bytes)))throw HttpException::conflict('Photo integrity check failed.');$this->audit->record('found_property','photo_viewed',$id);return ['base64'=>$r['photo_base64'],'mime'=>$r['photo_mime'],'sha256'=>$r['photo_sha256']];}
    public function action(string $id,string $action,array $input):array {return $this->atomic(function()use($id,$action,$input){$allowed=match($action){'move'=>['expected_revision','storage_location','notes'],'collect'=>['expected_revision','claimant_name','identity_checked','signature_base64','notes'],'dispose'=>['expected_revision','notes'],default=>throw HttpException::notFound()};$this->fields($input,$allowed);$r=$this->item($id);if($r['state']!=='STORED'||$this->number($input['expected_revision']??null)!==(int)$r['revision'])throw HttpException::conflict('Item changed or already left storage.');$notes=$this->text($input['notes']??null,2000);$state='STORED';$claimant=null;$signature=null;$hash=null;$storage=$r['storage_location'];if($action==='collect'){if(($input['identity_checked']??null)!==true)throw HttpException::unprocessable('Confirm identity and entitlement to collect.');$claimant=$this->text($input['claimant_name']??null,150);$sig=WorkflowMedia::image($input['signature_base64']??null,true);$signature=$sig['base64'];$hash=$sig['sha256'];$state='COLLECTED';}elseif($action==='dispose')$state='DISPOSED';else $storage=$this->text($input['storage_location']??null,300);$this->db->execute('INSERT INTO found_property_events(company_id,property_id,event_type,notes,claimant_name,signature_base64,signature_sha256,storage_location,actor_user_id,occurred_at) VALUES(:company,:id,:type,:notes,:name,:signature,:hash,:storage,:actor,:now)',['company'=>$this->company(),'id'=>$id,'type'=>strtoupper($action),'notes'=>$notes,'name'=>$claimant,'signature'=>$signature,'hash'=>$hash,'storage'=>$storage,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);$event=(string)$this->db->connection()->lastInsertId();$this->db->execute('UPDATE found_property SET state=:state,storage_location=:storage,revision=revision+1 WHERE company_id=:company AND property_id=:id',['state'=>$state,'storage'=>$storage,'company'=>$this->company(),'id'=>$id]);$this->audit->record('found_property',$action,$id);return ['state'=>$state,'event_id'=>$event];});}
    public function receipt(string $id):array {$r=$this->item($id);unset($r['photo_base64']);$events=$this->db->fetchAll("SELECT * FROM found_property_events WHERE company_id=:company AND property_id=:id AND event_type='COLLECT' ORDER BY event_id",['company'=>$this->company(),'id'=>$id]);foreach($events as$e){$bytes=base64_decode($e['signature_base64'],true);if($bytes===false||!hash_equals($e['signature_sha256'],hash('sha256',$bytes)))throw HttpException::conflict('Signature integrity check failed.');}$this->audit->record('found_property','receipt_viewed',$id);return ['item'=>$r,'collections'=>$events,'note'=>'Recorded collection attestation; identity and ownership must be verified by staff.'];}
}
